# -*- coding: utf-8 -*-
"""Core: deterministic PNG encoder/decoder, drawing primitives, bitmap text engine."""
import base64, json, math, struct, zlib

W = H = 1024
MARGIN = 24
GLYPHS = [0]          # total characters typeset


# ---------------------------------------------------------------- PNG codec
def write_png(path, buf):
    raw = bytearray()
    stride = W * 3
    for y in range(H):
        raw.append(0)
        raw += buf[y * stride:(y + 1) * stride]
    comp = zlib.compress(bytes(raw), 9)

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        c += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
        return c

    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    png = (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
           + chunk(b"IDAT", comp) + chunk(b"IEND", b""))
    with open(path, "wb") as fh:
        fh.write(png)
    return png


def png_valid(path):
    """Parse the written file: signature, IHDR, inflate IDAT, check size + CRC."""
    try:
        with open(path, "rb") as fh:
            data = fh.read()
        if data[:8] != b"\x89PNG\r\n\x1a\n":
            return False, None
        pos, idat, ihdr = 8, b"", None
        while pos + 8 <= len(data):
            ln = struct.unpack(">I", data[pos:pos + 4])[0]
            tag = data[pos + 4:pos + 8]
            body = data[pos + 8:pos + 8 + ln]
            crc = struct.unpack(">I", data[pos + 8 + ln:pos + 12 + ln])[0]
            if zlib.crc32(tag + body) & 0xFFFFFFFF != crc:
                return False, None
            if tag == b"IHDR":
                ihdr = struct.unpack(">IIBBBBB", body)
            elif tag == b"IDAT":
                idat += body
            pos += 12 + ln
        if ihdr is None:
            return False, None
        w, h, depth, ctype = ihdr[0], ihdr[1], ihdr[2], ihdr[3]
        if depth != 8 or ctype != 2:
            return False, None
        plain = zlib.decompress(idat)
        if len(plain) != h * (1 + w * 3):
            return False, None
        return True, (w, h)
    except Exception:
        return False, None


# ---------------------------------------------------------------- primitives
def new_page(color=(247, 244, 236)):
    return bytearray(bytes(color) * (W * H))


def put(buf, x, y, col, a=1.0):
    if 0 <= x < W and 0 <= y < H:
        i = (y * W + x) * 3
        if a >= 1.0:
            buf[i] = col[0]; buf[i + 1] = col[1]; buf[i + 2] = col[2]
        else:
            buf[i] = int(buf[i] + (col[0] - buf[i]) * a)
            buf[i + 1] = int(buf[i + 1] + (col[1] - buf[i + 1]) * a)
            buf[i + 2] = int(buf[i + 2] + (col[2] - buf[i + 2]) * a)


def rect(buf, x, y, w, h, col):
    x0, y0 = max(0, int(x)), max(0, int(y))
    x1, y1 = min(W, int(x + w)), min(H, int(y + h))
    if x1 <= x0 or y1 <= y0:
        return
    row = bytes(col) * (x1 - x0)
    for yy in range(y0, y1):
        i = (yy * W + x0) * 3
        buf[i:i + len(row)] = row


def grad_rect(buf, x, y, w, h, top, bot, vertical=True):
    x0, y0 = max(0, int(x)), max(0, int(y))
    x1, y1 = min(W, int(x + w)), min(H, int(y + h))
    for yy in range(y0, y1):
        for xx in range(x0, x1):
            if vertical:
                t = (yy - y0) / max(1, (y1 - y0 - 1))
            else:
                t = (xx - x0) / max(1, (x1 - x0 - 1))
            put(buf, xx, yy, (int(top[0] + (bot[0] - top[0]) * t),
                              int(top[1] + (bot[1] - top[1]) * t),
                              int(top[2] + (bot[2] - top[2]) * t)))


def hline(buf, x, y, w, col, t=1):
    rect(buf, x, y, w, t, col)


def vline(buf, x, y, h, col, t=1):
    rect(buf, x, y, t, h, col)


def ellipse(buf, cx, cy, rx, ry, col):
    if rx <= 0 or ry <= 0:
        return
    for yy in range(max(0, int(cy - ry)), min(H, int(cy + ry) + 1)):
        dy = (yy + 0.5 - cy) / ry
        if abs(dy) > 1:
            continue
        dx = rx * math.sqrt(1 - dy * dy)
        rect(buf, int(cx - dx), yy, int(dx * 2), 1, col)


def circle(buf, cx, cy, r, col):
    ellipse(buf, cx, cy, r, r, col)


def poly(buf, pts, col, bbox=None):
    xs = [p[0] for p in pts]; ys = [p[1] for p in pts]
    if bbox is None:
        x0, x1 = max(0, int(min(xs))), min(W, int(max(xs)) + 1)
        y0, y1 = max(0, int(min(ys))), min(H, int(max(ys)) + 1)
    else:
        x0, y0, x1, y1 = bbox
        x0 = max(0, int(x0)); y0 = max(0, int(y0))
        x1 = min(W, int(x1)); y1 = min(H, int(y1))
    n = len(pts)
    for yy in range(y0, y1):
        py = yy + 0.5
        for xx in range(x0, x1):
            px = xx + 0.5
            inside = False
            j = n - 1
            for i in range(n):
                xi, yi = pts[i]; xj, yj = pts[j]
                if (yi > py) != (yj > py):
                    if px < (xj - xi) * (py - yi) / (yj - yi + 1e-9) + xi:
                        inside = not inside
                j = i
            if inside:
                put(buf, xx, yy, col)


def thick_line(buf, x0, y0, x1, y1, col, t=2):
    n = int(max(abs(x1 - x0), abs(y1 - y0))) + 1
    for i in range(n + 1):
        px = x0 + (x1 - x0) * i / n
        py = y0 + (y1 - y0) * i / n
        rect(buf, int(px - t / 2), int(py - t / 2), t, t, col)

# -*- coding: utf-8 -*-
"""Bitmap text engine (glyph atlas blitting) + procedural photo-box illustrations."""
import math

FONT = json.loads(FONTJSON)
_GCACHE = {}


def _glyph(style, ch):
    g = _GCACHE.get((style, ch))
    if g is None:
        entry = FONT[style].get(ch) or FONT[style].get("?") or FONT[style].get(" ")
        bw, bh, adv, b64 = entry
        raw = base64.b64decode(b64) if b64 else b""
        g = (bw, bh, adv, raw)
        _GCACHE[(style, ch)] = g
    return g


def measure(style, s):
    return sum(_glyph(style, c)[2] for c in s)


def draw_text(buf, style, s, x, y, col, count=True):
    """Blit string s; (x, y) is top-left of the glyph box. Returns advance."""
    cx = int(x)
    for ch in s:
        bw, bh, adv, raw = _glyph(style, ch)
        if raw:
            for gy in range(bh):
                yy = y + gy
                if yy < 0 or yy >= H:
                    continue
                base = gy * bw
                row_runs = []
                run = None
                for gx in range(bw):
                    bit = (raw[(base + gx) >> 3] >> (7 - ((base + gx) & 7))) & 1
                    if bit and run is None:
                        run = gx
                    elif not bit and run is not None:
                        row_runs.append((run, gx)); run = None
                if run is not None:
                    row_runs.append((run, bw))
                for a, b in row_runs:
                    xx0, xx1 = cx + a, cx + b
                    if xx0 < 0 or xx1 > W:
                        xx0, xx1 = max(0, xx0), min(W, xx1)
                    if xx1 > xx0:
                        i = (yy * W + xx0) * 3
                        buf[i:i + (xx1 - xx0) * 3] = bytes(col) * (xx1 - xx0)
        cx += adv
    if count:
        GLYPHS[0] += len(s)
    return cx - int(x)


def draw_center(buf, style, s, cx, y, col):
    return draw_text(buf, style, s, int(cx - measure(style, s) / 2), y, col)


def wrap(style, text, width):
    words, lines, cur = text.split(), [], ""
    for wd in words:
        trial = wd if not cur else cur + " " + wd
        if measure(style, trial) <= width or not cur:
            cur = trial
        else:
            lines.append(cur); cur = wd
    if cur:
        lines.append(cur)
    return lines


def paragraph(buf, style, text, x, y, width, lh, col, max_lines=99, count=True):
    lines = wrap(style, text, width)
    if len(lines) > max_lines:
        lines = lines[:max_lines]
        tail = lines[-1]
        while tail and measure(style, tail + "...") > width:
            tail = tail[:-1].rstrip()
        lines[-1] = tail + "..."
    for i, ln in enumerate(lines):
        draw_text(buf, style, ln, x, y + i * lh, col, count=count)
    return y + len(lines) * lh


# ---------------------------------------------------------------- illustrations
def frame(buf, x, y, w, h, col, t=1):
    rect(buf, x, y, w, t, col); rect(buf, x, y + h - t, w, t, col)
    rect(buf, x, y, t, h, col); rect(buf, x + w - t, y, t, h, col)


def curve(buf, pts, col, t=2):
    for i in range(len(pts) - 1):
        thick_line(buf, pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], col, t)


def turbine(buf, cx, base, scale, mast=(236, 238, 240), blade=(246, 247, 248)):
    tw = max(2, int(scale * 0.06))
    rect(buf, cx - tw // 2, int(base - scale), tw, int(scale), mast)
    r = scale * 0.42
    for ang in (95, 215, 335):
        a = math.radians(ang)
        curve(buf, [(cx, base - scale),
                    (cx + r * math.cos(a), base - scale + r * math.sin(a))],
              blade, max(2, int(scale * 0.07)))
    circle(buf, cx, base - scale, max(2, int(scale * 0.05)), (210, 214, 218))


def solar_row(buf, x, y, w, h, sky):
    pw = max(6, w // 6)
    for i in range(5):
        px = x + i * (pw + 3)
        if px + pw > x + w:
            break
        poly(buf, [(px, y + h), (px + pw, y + h - h * 0.35),
                   (px + pw, y + h), (px, y + h)], (34, 52, 84))
        rect(buf, px, y + int(h * 0.62), pw, max(2, int(h * 0.38)), (38, 60, 102))
        for k in range(1, 3):
            vline(buf, px + k * pw // 3, y + int(h * 0.62), int(h * 0.38), (86, 116, 168))
    hline(buf, x, y + h - 1, w, (60, 66, 54), 2)

