"""Photo-box scenes: small deterministic illustrations, one per story."""
import math


def _stars(buf, x, y, w, h, n=40):
    for i in range(n):
        sx = x + 3 + ((i * 7919 + 13) % max(1, w - 6))
        sy = y + 3 + ((i * 6271 + 29) % max(1, h - 6))
        c = 150 + (i * 37) % 105
        rect(buf, sx, sy, 1 + (i % 2), 1 + (i % 2), (c, c, min(255, c + 18)))


