# -*- coding: utf-8 -*-
"""Page layout: masthead, lead story, 4x4 news grid, footer. Draws the frame."""
PAPER = (247, 244, 236)
INK = (26, 24, 22)
BODY = (48, 46, 44)
MUTED = (110, 106, 100)
ACCENT = (166, 44, 40)
RULE = (176, 170, 158)

SEC_COLOR = {
    "AI": (34, 92, 164), "ENERGY": (30, 118, 70), "MARKETS": (24, 72, 130),
    "SPACE": (94, 68, 150), "SCIENCE": (22, 110, 132), "HEALTH": (174, 56, 62),
    "WEATHER": (58, 108, 172), "TRANSPORT": (148, 88, 28), "SPORTS": (176, 92, 26),
    "CULTURE": (126, 58, 128), "TOP STORY": (166, 44, 40),
}

# grid geometry
GX0, GY0 = 24, 330
CW, CH, GAP = 236, 159, 8
CGAP = 10


def right_text(buf, style, s, xr, y, col):
    draw_text(buf, style, s, int(xr - measure(style, s)), y, col)


def build_frame():
    GLYPHS[0] = 0
    buf = new_page()
    cw = W - 2 * MARGIN            # 976

    # ---- masthead rules + title
    hline(buf, MARGIN, 14, cw, INK, 3)
    hline(buf, MARGIN, 20, cw, INK, 1)
    draw_center(buf, "mast", MASTHEAD, W / 2, 28, INK)
    hline(buf, MARGIN, 74, cw, INK, 2)

    # ---- kicker row: edition / dateline / issue
    draw_text(buf, "sec", EDITION, MARGIN, 80, BODY)
    draw_center(buf, "date", DATELINE, W / 2, 78, INK)
    right_text(buf, "sec", LATE + "  -  " + ISSUE, W - MARGIN, 80, BODY)
    hline(buf, MARGIN, 96, cw, INK, 1)
    hline(buf, MARGIN, 99, cw, RULE, 1)

    # ---- lead story (left text column, right photo)
    LX, LW = MARGIN, 704
    RX, RW = 744, W - MARGIN - 744
    k = measure("kick", LEAD["kicker"]) + 18
    rect(buf, LX, 106, k, 15, SEC_COLOR["TOP STORY"])
    draw_text(buf, "kick", LEAD["kicker"], LX + 9, 108, (255, 252, 246))
    draw_text(buf, "lead", LEAD["hl"][0], LX, 126, INK)
    draw_text(buf, "lead", LEAD["hl"][1], LX, 157, INK)
    hline(buf, LX, 194, 44, ACCENT, 3)
    paragraph(buf, "body", LEAD["sum"], LX, 203, LW, 15, BODY, max_lines=7)

    draw_photo(buf, "lead", RX, 106, RW, 168)
    paragraph(buf, "cap", LEAD["cap"], RX, 280, RW, 11, MUTED, max_lines=2)

    # ---- section bar
    rect(buf, MARGIN, 304, cw, 22, INK)
    draw_text(buf, "kick", BRIEF, MARGIN + 10, 309, (250, 247, 240))
    tail = DATELINE
    right_text(buf, "tiny", tail, W - MARGIN - 10, 311, (206, 200, 190))

    # ---- 4 x 4 grid of stories
    for i, (sec, hl, sm, icon) in enumerate(STORIES):
        r, c = divmod(i, 4)
        x = GX0 + c * (CW + CGAP)
        y = GY0 + r * (CH + GAP)
        col = SEC_COLOR.get(sec, INK)
        draw_photo(buf, icon, x, y, CW, 52)
        rect(buf, x, y + 57, 6, 8, col)
        draw_text(buf, "kick", sec, x + 10, 57 + y, col)
        paragraph(buf, "hl", hl, x, y + 67, CW, 17, INK, max_lines=2)
        paragraph(buf, "body", sm, x, y + 103, CW, 14, BODY, max_lines=4)

    # column hairlines
    for c in range(1, 4):
        vline(buf, GX0 + c * (CW + CGAP) - 6, GY0, 4 * CH + 3 * GAP, RULE, 1)

    # ---- footer
    hline(buf, MARGIN, 996, cw, INK, 1)
    draw_text(buf, "tiny", FOOT_L, MARGIN, 1001, MUTED)
    right_text(buf, "tiny", FOOT_R, W - MARGIN, 1001, MUTED)
    return buf


def render_png(path):
    """Render, encode, verify. Returns (png_bytes, stats_dict)."""
    buf = build_frame()
    glyphs = GLYPHS[0]
    buf2 = build_frame()
    deterministic = (bytes(buf) == bytes(buf2)) and (GLYPHS[0] == glyphs)
    png = write_png(path, buf)
    ok, dims = png_valid(path)
    stats = {
        "narration_count": 1 + len(STORIES),
        "glyph_count": glyphs,
        "png_valid": bool(ok),
        "width_height": list(dims) if dims else [0, 0],
        "file_bytes": len(png),
        "deterministic": bool(deterministic),
    }
    return png, stats


def main():
    import os, sys, tempfile
    here = os.path.dirname(os.path.abspath(__file__))
    preset = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if preset:
        cands = [preset]
    else:
        cands = ["/output"]
        if os.path.abspath(os.getcwd()) != os.path.abspath(here):
            cands.append(os.path.join(os.getcwd(), "output"))
        cands.append(os.path.join(tempfile.gettempdir(), "makefun_output"))
    out_dir = cands[-1]
    for cand in cands:
        try:
            os.makedirs(cand, exist_ok=True)
            out_dir = cand
            break
        except OSError:
            continue
    path = os.path.join(out_dir, "entry.png")
    _, stats = render_png(path)
    sys.stdout.write(json.dumps(stats) + "\n")
    return 0 if (stats["png_valid"] and stats["deterministic"]
                 and stats["file_bytes"] <= 1024 * 1024
                 and stats["width_height"][0] <= 1024
                 and stats["width_height"][1] <= 1024) else 1


if __name__ == "__main__":
    raise SystemExit(main())
